#!/usr/bin/env bash
# СУДИТ: hooks/guarantee-map-guard.sh
# probe_D1169 — страж карты гарантий опознаёт находку, адрес и карту по РОЛИ, а не по вёрстке строки: формы из отчётов
# скептиков D1158 (находка через пустую строку, пунктом списка, подзаголовком; адрес в заборе кода, абсолютный, в другом
# регистре, через `..`; метки противника и прожарки; карта со «скептиком» в метке, карта-заглушка, карта пунктом списка
# и прописными; `$README`; имя из двух и из трёх прописных) — ноги T18a–T18r теста стража; второй круг (гонка с
# писателем бэклога, регистр бэклога, пункт списка без роли, подзаголовок с отступом, `{…}`, `version`, хвостовая
# точка, метка в заборе, адрес прописными, абсолютный путь как дан и его граница) — T19a–T19o. Каждая судит как объявлено.
# Красная (1), пока тест стража красный либо ног T18/T19 меньше 28; 2 — рамка не собралась.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
T="$R/hooks/tests/test_guarantee_map_guard.sh"
[ -f "$T" ] && [ -f "$R/hooks/guarantee-map-guard.sh" ] || exit 2
[ "$(grep -cE '^judge T1[89][a-z] ' "$T")" -ge 28 ] || { echo "ног T18/T19 в тесте стража меньше 28"; exit 1; }
out=$(bash "$T" 2>&1); rc=$?
printf '%s\n' "$out" | grep -q 'guarantee-map-guard: [0-9]* passed, 0 failed' && [ "$rc" -eq 0 ] && exit 0
printf '%s\n' "$out" | grep 'FAIL' | head -20
exit 1
